import {games,moods,filterGames} from './games.js';
const $=s=>document.querySelector(s);const params=new URLSearchParams(location.search);
const clamp=n=>Math.min(20,Math.max(2,Number(n)||4));
const state={players:clamp(params.get('n')||4),duration:[0,10,20,40].includes(Number(params.get('t')))?Number(params.get('t')):0,equipment:['any','none','paper'].includes(params.get('e'))?params.get('e'):'any',mood:Object.hasOwn(moods,params.get('m'))?params.get('m'):'all',savedOnly:false,saved:[],query:(params.get('q')||'').slice(0,100)};
try{const saved=JSON.parse(localStorage.getItem('sobralis.saved')||'[]');if(Array.isArray(saved))state.saved=saved.filter(id=>games.some(g=>g.id===id));}catch{}
let current=null,previousRandom=null,toastTimeout,timerInterval=null,remaining=60,deadline=0;
const dialog=$('#game-dialog');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3300);}
function people(n){return n===2?'человека':n%10===1&&n!==11?'человек':n%10>=2&&n%10<=4&&(n<12||n>14)?'человека':'человек';}
function syncInputs(){$('#clear-search').hidden=!state.query;$('#players').value=state.players;$('#players').nextElementSibling.textContent=people(state.players);$('#minus').disabled=state.players<=2;$('#plus').disabled=state.players>=20;$('#duration').value=state.duration;$('#equipment').value=state.equipment;document.querySelectorAll('[data-mood]').forEach(b=>{const active=b.dataset.mood===state.mood;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});$('#saved-toggle').setAttribute('aria-pressed',state.savedOnly);$('#saved-count').textContent=state.saved.length;}
function metadata(g){return `<span>♙ ${g.min}–${g.max} игроков</span><span>◷ ${g.time} мин</span><span>${g.equipment==='none'?'✧ Без реквизита':'✎ Бумага и ручки'}</span>`;}
function render(){syncInputs();const found=filterGames(state);$('#result-count').textContent=found.length;$('#results-title').firstChild.textContent=state.savedOnly?'Любимые игры ':'Ваш следующий отличный вечер ';$('#result-caption').textContent=state.savedOnly?'Избранное хранится в этом браузере. Фильтры тоже учитываются.':'Выбирайте по настроению. Правила уже внутри.';$('#games').innerHTML=found.map(g=>`<article class="game"><div class="game-visual ${g.color}"><span class="game-badge">${g.tag}</span><button class="save-button" data-save="${g.id}" aria-pressed="${state.saved.includes(g.id)}" aria-label="${state.saved.includes(g.id)?'Убрать из избранного':'В избранное'}: ${g.name}">${state.saved.includes(g.id)?'♥':'♡'}</button><span class="visual-symbol" aria-hidden="true">${g.symbol}</span></div><div class="game-content"><h3>${g.name}</h3><p class="game-description">${g.desc}</p><div class="meta">${metadata(g)}</div><div class="game-bottom"><span>${g.level}</span><button class="rules-button" data-open="${g.id}">Как играть ↗<span class="sr-only"></span></button></div></div></article>`).join('');$('#empty').hidden=found.length>0;$('#empty-text').textContent=state.query?'По этому названию с текущими фильтрами ничего нет. Проверьте написание или сбросьте поиск и фильтры.':state.savedOnly?'Добавьте игры сердечком или измените фильтры, чтобы увидеть сохранённые варианты.':'Попробуйте убрать один из фильтров — и появятся новые варианты.';$('#random').disabled=!found.length;}
function toggleSave(id){const exists=state.saved.includes(id);state.saved=exists?state.saved.filter(x=>x!==id):[...state.saved,id];try{localStorage.setItem('sobralis.saved',JSON.stringify(state.saved));}catch{toast('Браузер не разрешил сохранение. Избранное доступно до перезагрузки.');}render();syncDialogSave();}
function syncDialogSave(){if(current)$('#dialog-save').textContent=state.saved.includes(current.id)?'♥ Убрать из избранного':'♡ Сохранить на следующий вечер';}
function openGame(id){const g=games.find(g=>g.id===id);if(!g)return;current=g;resetTimer();$('#dialog-category').textContent=moods[g.mood];$('#dialog-art').className=`dialog-art ${g.color}`;$('#dialog-art').textContent=g.symbol;$('#dialog-title').textContent=g.name;$('#dialog-desc').textContent=g.desc;$('#dialog-meta').innerHTML=metadata(g);$('#dialog-equipment').textContent=g.needs;$('#dialog-rules').replaceChildren(...g.rules.map(rule=>{const li=document.createElement('li');li.textContent=rule;return li;}));$('#dialog-tip').textContent=g.tip;syncDialogSave();if(!dialog.open)dialog.showModal();}
function stopTimer(){clearInterval(timerInterval);timerInterval=null;$('#timer-start').textContent=remaining<=0?'Заново':'Старт';}
function displayTime(){$('#timer-display').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;}
function resetTimer(){stopTimer();remaining=Number($('#timer-length').value);$('#timer-start').textContent='Старт';$('#timer-status').textContent='';displayTime();}
function tick(){remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));displayTime();if(remaining===0){stopTimer();$('#timer-status').textContent='Время вышло! Передавайте ход следующему игроку.';}}
$('#timer-start').addEventListener('click',()=>{if(timerInterval){tick();stopTimer();$('#timer-start').textContent=remaining>0?'Продолжить':'Заново';return;}if(remaining<=0)resetTimer();deadline=Date.now()+remaining*1000;$('#timer-start').textContent='Пауза';$('#timer-status').textContent='Раунд идёт';timerInterval=setInterval(tick,200);});
$('#timer-reset').addEventListener('click',resetTimer);$('#timer-length').addEventListener('change',resetTimer);dialog.addEventListener('close',resetTimer);$('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
$('#games').addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save)toggleSave(save.dataset.save);const open=e.target.closest('[data-open]');if(open)openGame(open.dataset.open);});$('#dialog-save').addEventListener('click',()=>current&&toggleSave(current.id));
$('#players').addEventListener('change',e=>{state.players=clamp(e.target.value);render();});$('#minus').addEventListener('click',()=>{state.players=clamp(state.players-1);render();});$('#plus').addEventListener('click',()=>{state.players=clamp(state.players+1);render();});$('#duration').addEventListener('change',e=>{state.duration=Number(e.target.value);render();});$('#equipment').addEventListener('change',e=>{state.equipment=e.target.value;render();});$('#moods').addEventListener('click',e=>{const b=e.target.closest('[data-mood]');if(b){state.mood=b.dataset.mood;render();}});$('#saved-toggle').addEventListener('click',()=>{state.savedOnly=!state.savedOnly;render();$('#picker').scrollIntoView({behavior:'smooth'});});
$('#game-search').value=state.query;$('#game-search').addEventListener('input',e=>{state.query=e.target.value;render();});$('#clear-search').addEventListener('click',()=>{state.query='';$('#game-search').value='';render();$('#game-search').focus();});
function reset(){Object.assign(state,{players:4,duration:0,equipment:'any',mood:'all',savedOnly:false,query:''});$('#game-search').value='';render();}$('#reset').addEventListener('click',reset);$('#empty-reset').addEventListener('click',reset);
$('#random').addEventListener('click',()=>{let found=filterGames(state);if(found.length>1)found=found.filter(g=>g.id!==previousRandom);if(found.length){const g=found[Math.floor(Math.random()*found.length)];previousRandom=g.id;openGame(g.id);}});
$('#share').addEventListener('click',async()=>{const url=new URL(location.href);url.search='';url.hash='picker';url.searchParams.set('n',state.players);if(state.query.trim())url.searchParams.set('q',state.query.trim());if(state.duration)url.searchParams.set('t',state.duration);if(state.equipment!=='any')url.searchParams.set('e',state.equipment);if(state.mood!=='all')url.searchParams.set('m',state.mood);try{await navigator.clipboard.writeText(url.href);toast('Ссылка на подборку скопирована. Отправьте её друзьям!');}catch{try{if(navigator.share)await navigator.share({title:'Собрались — во что поиграть?',url:url.href});else window.prompt('Скопируйте ссылку на подборку:',url.href);}catch(e){if(e.name!=='AbortError')toast('Не удалось поделиться ссылкой. Попробуйте ещё раз.');}}});
render();
